#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    int half = n / 2;
    for (int i = 0; i < (n - half) / 2; i++) {
        long long tmp = a[half + i]; a[half + i] = a[n - 1 - i]; a[n - 1 - i] = tmp;
    }
    for (int i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%lld", a[i]);
    }
    printf("\n");
    return 0;
}

