#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    int half = n / 2;
    reverse(a.begin() + half, a.end());
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << a[i];
    }
    cout << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextLong();
            int half = n / 2;
            for (int i = 0; i < (n - half) / 2; i++) {
                long tmp = a[half + i]; a[half + i] = a[n - 1 - i]; a[n - 1 - i] = tmp;
            }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if (i > 0) sb.append(" ");
                sb.append(a[i]);
            }
            System.out.println(sb.toString());
        }
    }
}

