const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const half = Math.floor(n / 2);
    const first = toks.slice(1, half + 1);
    const second = toks.slice(half + 1, n + 1).reverse();
    console.log(first.concat(second).join(" "));
}
main();

